// Ported from the Node app's Sequelize model TransportStaff (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class TransportStaffConfiguration : IEntityTypeConfiguration<TransportStaff>
{
    public void Configure(EntityTypeBuilder<TransportStaff> builder)
    {
        builder.ToTable("transport_staff", t =>
        {
            t.HasCheckConstraint("CK_transport_staff_role", "[role] IN (N'driver', N'attendant')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Role).HasColumnName("role").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Phone).HasColumnName("phone").HasColumnType("nvarchar(20)").HasMaxLength(20);
        builder.Property(e => e.LicenseNo).HasColumnName("license_no").HasColumnType("nvarchar(40)").HasMaxLength(40);
        builder.Property(e => e.LicenseExpiry).HasColumnName("license_expiry").HasColumnType("date");
        builder.Property(e => e.VehicleId).HasColumnName("vehicle_id");
        builder.HasOne(e => e.Vehicle).WithMany(p => p.TransportStaffs).HasForeignKey(e => e.VehicleId).OnDelete(DeleteBehavior.NoAction);
    }
}
